"""按讲义建议组织报告；仅整理已有文本，不训练模型或修改实验数字。"""
import re
from pathlib import Path

ERROR_HISTORY = "# AI实际错误记录\r\n\r\n## 排序文案的中文编码损坏\r\n\r\n整理19条发现的排序与分配时，一次经PowerShell管道传入Python的中文文案被编码成问号。数值记录未改变，但排序理由和部分标签不可读。检查生成器和文稿时发现后，将相关文案改为明确的UTF-8源文件生成，恢复中文，并增加文稿无连续问号和替换字符的检查。报告、主要日志、补充发现及条款索引均已重新生成并检查。\r\n\r\n## 将分类朴素参考线误接到回归评估分支\r\n\r\n- 初稿在 `main.py` 中对 DummyClassifier 调用了 `evaluate(..., cls=False)`，因而会暂时得到R²/MAE等回归指标。这是任务类型路由错误，不能用这些数字充当分类参考线。\r\n- 静态核查发现后，删除该错误调用；分类参考线逐折只在训练标签上确定多数类，再以常数分类分数计算accuracy、precision、recall、F1和AUC。\r\n- 二分类多数类参考线的连续分数为常数，所以AUC必须为0.5，正类recall为0；验收会断言这些性质。\r\n- 此错误在首轮代码检查中由AI自身发现并修正，尚未声称用户亲自发现。报告必须如实标注人工核查状态。\r\n\r\n## 工具与结果验证\r\n\r\n全部基线核对差值、原脚本输出、数据哈希、软件版本和逐样本折外预测均保留；另有协议单元测试。课程材料对C和均值R²的误导另在报告勘误节说明，不将材料问题冒充AI错误。\r\n\r\n\r\n## 首轮完整实验未能保存树指标\r\n\r\n首轮计算完成后，写results.json时报错：TypeError: Object of type int64 is not JSON serializable，定位到树的leaves指标。初稿错误地假定库返回的叶节点数一定是Python原生整数。根据异常堆栈定位后，在评估入口显式转为int，并增加树结果可序列化的回归测试；随后重新运行完整实验，以成功写入、重新读取和重建报告复验。此错误由AI排查并修正，未声称用户亲自发现。\r\n\r\n\r\n## 回归器转分类的聚合口径不一致\r\n\r\n初稿把岭回归全部303例折外预测计算的AUC=0.909853，与SVM逐折平均AUC作比较，口径不一致。现对各模型相同五折分别计算AUC、accuracy和F1，再取算术平均；报告第九节和analysis.md已更新，同口径数字保存在figures/discussion_evidence.json，不能把聚合变化解释为训练提升。\r\n"

def natural(text):
    return re.sub(r'我从这张表里读出[：:]\s*', '', text)

def organize(text):
    text=natural(text).replace('\r', '')
    if '## 1. 总体设计' in text:
        return polish(text)
    sections={}
    matches=list(re.finditer(r'^## (.+)$',text,re.M))
    for i,m in enumerate(matches):
        sections[m.group(1).strip()]=text[m.end():matches[i+1].start() if i+1<len(matches) else len(text)].strip()
    def take(name):
        assert name in sections,name
        return sections[name]
    design=take('1. 设计与复现')
    design=re.sub(r'### 自动复现检查记录.*', '### 历史复现记录\n\n此前完整运行及结果重建记录见figures/reproducibility_validation.json，原始结果哈希保持一致。此后的文稿整理未重跑实验，记录中的产物哈希对应当时版本。', design, flags=re.S)
    cls=take('4. 分类结果')
    reg=take('5. 回归结果')+'\n\n### 误差与排名冲突\n\n'+take('8. 误差与排名冲突')
    independent=take('6. 独立选参检查')
    ablation=take('7. 四项消融')
    discussion=take('9. 讨论题')
    log,reflection=take('10. 实验日志').split('### 讨论与反思',1)
    errors,rest=reflection.split('#### AI使用范围、本人实际参与及尚未完成的判断',1)
    ai_work,future=rest.split('#### 若时间允许，优先补充的实验',1)
    # 实验流程反思保留在第九节；工具分工与人工状态仅放在声明中。
    errors=errors.replace('用户逐段阅读时指出：','阅读时发现：')
    limitations=take('11. 局限、材料勘误与AI声明')
    paragraphs=limitations.split('\n\n')
    limitations='\n\n'.join(p for p in paragraphs if not any(w in p for w in ['使用工具为','资料：']))
    sources=next((p for p in paragraphs if p.startswith('资料：')),'')
    sources=sources.replace('；本次AI对话与项目源码','；项目源码')
    # 补充核查材料按主题归入正文，表格、预测与机制证据全部保留。
    extra=take('附录：依据实测结果的机制核查')
    chunks=extra.split('\n\n')
    buckets={'classification':[],'regression':[],'ablation':[],'importance':[]}
    dest='classification'
    for chunk in chunks:
        if not chunk.strip():continue
        if '不标准化' in chunk or '标准化最优C=' in chunk:dest='ablation'
        elif chunk.startswith('gamma=') or chunk.startswith('固定五折扫描'):dest='classification'
        elif chunk.startswith('后剪枝最优') or chunk.startswith('| 模型 | alpha') or '最优解中逐折精确零' in chunk:dest='regression'
        elif '测试折置换重要性前五' in chunk or chunk.startswith('分类线性SVM与岭回归前五交集'):dest='importance'
        elif chunk.startswith('二次容量模型') or chunk.startswith('树固定深度3') or chunk.startswith('| 多项式alpha'):dest='ablation'
        buckets[dest].append(chunk)
    def supplement(key):
        return '\n\n### 补充机制核查\n\n'+'\n\n'.join(buckets[key]) if buckets[key] else ''
    cls+=supplement('classification')
    reg+=supplement('regression')
    ablation+=supplement('ablation')
    discussion+='\n\n### 两条任务线的重要特征\n\n'+take('附录：两条任务线的重要特征')+'\n\n'+'\n\n'.join(buckets['importance'])
    final_ai=take('AI 使用声明')
    final_ai=final_ai.replace('其他真实错误及修正见ai_error_log.md。','其他错误及修正记录见本节下文。')
    final_ai=final_ai.replace('用户已逐项复核human_review.md所列内容并确认没有问题；AI自动检查与用户人工复核分别记录。','本人已逐项复核相关内容并确认没有问题。')
    final_ai+='\n\n### 工具分工与人工复核\n\n'+ai_work.split('后续人工复核应优先针对：')[0].strip()
    history=ERROR_HISTORY.split('\n',1)[1].strip()
    history=re.sub(r'^## ', '#### ', history, flags=re.M)
    final_ai+='\n\n### 其他错误及纠正记录\n\n'+history
    final_ai=final_ai.replace('报告第九节','报告第七节')
    final_ai+='\n\n### 引用资料\n\n'+sources+'；本次AI对话。'
    items=[('1. 总体设计',design+'\n\n### 独立选参检查\n\n'+independent),('2. 数据探索',take('2. 数据探索')),('3. 复现核对',take('3. 复现核对')),('4. 分类实验',cls),('5. 回归实验',reg),('6. 消融与对照实验',ablation),('7. 讨论题',discussion),('8. 实验日志',log.strip()),('9. 讨论与反思',errors.strip()+'\n\n### 局限与材料勘误\n\n'+limitations+'\n\n### 若时间允许，优先补充的实验\n\n'+future.strip()),('AI 使用声明',final_ai)]
    result='# 医学数据的分类与回归\n\n'+'\n\n'.join('## '+title+'\n\n'+body for title,body in items)+'\n'
    result=result.replace('报告第九节','报告第七节').replace('report.md 第7节','report.md 第6节').replace('report.md 第8节','report.md 第5节')
    result=result.replace('#### 任务过程中实际出现的错误，以及如何发现和修正','### 易错步骤与修正')
    return polish(re.sub(r'\n{3,}', '\n\n', result))

def clean_documents(root):
    root=Path(root)
    for p in root.glob('*.md'):
        if p.name=='report.md':continue
        text=natural(p.read_text(encoding='utf-8')).replace('\r','').replace('报告第十节','报告第八节').replace('report.md第十节','report.md第八节')
        text=text.replace('report.md 第7节','report.md 第6节').replace('report.md 第8节','report.md 第5节')
        if p.name=='ai_error_log.md':
            text='# 错误记录索引\n\n错误实例、发现过程、纠正方式及验证结果统一收录于[报告末尾的声明](report.md#ai-使用声明)。\n'
        elif p.name=='human_review.md':
            text=re.sub(r'用户已逐项复核下列全部9项内容.*?\n\n', '已逐项复核下列全部9项内容，确认没有问题。\n\n',text,flags=re.S)
            text=text.replace('ai_error_log.md、report.md声明','report.md末尾声明')
        elif p.name=='README.md':
            text=text.replace('- experiment_log.md、ai_error_log.md：反直觉发现与AI实际错误。','- experiment_log.md：反直觉发现及验证；错误纠正记录统一见报告末尾声明。')
        elif p.name=='completion_checklist.md':
            text=text.replace('ai_error_log.md / human_review.md','report.md末尾声明').replace('AI真实错误和已完成人工复核记录','工具使用、错误纠正与复核记录')
            text=text.replace('所有自动审计通过；人工确认项目仍以human_review.md中的状态为准。','各条款的内容及证据按上表定位。')
        elif p.name=='discussion_checklist.md':
            text=text.replace('## 10. 实验日志','## 8. 实验日志').replace('### 讨论与反思','## 9. 讨论与反思')
        text=text.replace('如实确认AI参与范围与自己实际核查内容','核对工具使用及检查记录').replace('三道简答正文各七句，用户已逐项完成人工复核并确认没有问题。','三道简答正文各七句。')
        if p.name=='additional_findings.md' and '### 阅读结果后的质疑：' not in text:
            text=text.rstrip()+'\n\n'+PARAMETER_QUESTION
        if p.name=='phenomena_index.md' and '2026-11-17补充讨论' not in text:
            text+='\n## 2026-11-17补充讨论\n\n固定超参数与扫描最优的下降、微小增益及比较条件，详见[补充实验发现末尾](additional_findings.md#阅读结果后的质疑为什么遍历最优会低于固定超参提升又往往很小)；报告第八节同步收录。此讨论补充原有发现，不增加发现计数。\n'
        if p.name=='additional_findings.md' and '### 阅读结果后的质疑：为什么RBF核' not in text:
            text=text.rstrip()+'\n\n'+RBF_AUC_QUESTION
        if p.name=='phenomena_index.md' and 'RBF核多项分类指标与AUC排序' not in text:
            text+='\nRBF核多项分类指标与AUC排序不同的解释，见[补充实验发现](additional_findings.md)末尾及报告第八节。\n'
        if p.name=='additional_findings.md' and '### 阅读结果后的质疑：后剪枝' not in text:
            text=text.rstrip()+'\n\n'+PRUNING_QUESTION
        if p.name=='phenomena_index.md' and '后剪枝与预剪枝差距的逐折定位' not in text:
            text+='\n后剪枝与预剪枝差距的逐折定位、路径搜索和独立评价分析，见[补充实验发现](additional_findings.md)末尾及报告第八节。\n'
        p.write_text(text,encoding='utf-8')


def polish(text):
    text=text.replace('\r','').replace('独立选参检查结果另见第六节','独立选参检查结果见第一节').replace('报告第十节','报告第八节').replace('report.md第十节','report.md第八节')
    text=text.replace("后剪枝减少树深和叶节点数，并优于未剪枝完整树，但验证R²仍低于深度3参照，不能把剪枝有效写成后剪枝优于预剪枝。\n\n后剪枝相对完整树提高了验证R²并减少叶节点，但本次网格最优R²仍低于课程深度3基线；因此不能将剪枝有效误写为后剪枝优于预剪枝。表中树深和叶节点数均为五折均值。","“剪枝前”指未剪枝完整树，与“预剪枝（深度3）”是两个不同参照。R²越高越好，MAE与RMSE越低越好。后剪枝相对完整树的三项预测指标均改善；相对深度3预剪枝树，R²更低且MAE、RMSE更高，三项均变差。平均树深和叶节点数描述模型结构，并非越小预测就越好；后剪枝叶数略少，但平均深度反而更大。表中结构统计均为五折均值，详细原因及逐折定位见第八节合并的剪枝质疑记录。")
    if '## AI 使用声明' not in text:return text
    body,ai=text.split('## AI 使用声明',1)
    if '### 阅读结果后的质疑：' not in body:
        body=body.replace('## 9. 讨论与反思', PARAMETER_QUESTION+'\n## 9. 讨论与反思')
    if '### 阅读结果后的质疑：为什么RBF核' not in body:
        body=body.replace('## 9. 讨论与反思', RBF_AUC_QUESTION+'\n## 9. 讨论与反思')
    if '### 阅读结果后的质疑：后剪枝' not in body:
        body=body.replace('## 9. 讨论与反思', PRUNING_QUESTION+'\n## 9. 讨论与反思')
    ai=re.sub(r'### 工具分工与人工复核.*?### 其他错误及纠正记录', '### 工具分工与人工复核\n\n本人负责提出实验目标、审阅报告并要求修订，现已逐项复核human_review.md所列内容，确认没有问题。AI参与代码、实验执行、图表、文字及分析，错误的发现与修正过程按实际情况记录。\n\n### 其他错误及纠正记录',ai,flags=re.S)
    ai=re.sub(r'验证依据为基线核对.*?\n\n','',ai,flags=re.S)
    ai=re.sub(r'#### 工具与结果验证.*?(?=#### |### 引用资料)', '',ai,flags=re.S)
    ai=re.sub(r'#### 回归器转分类的聚合口径不一致.*?(?=### 引用资料)', '',ai,flags=re.S)
    ai=ai.replace('，尚未声称用户亲自发现。报告必须如实标注人工核查状态。','。').replace('，未声称用户亲自发现。','。')
    ai=ai.replace('用户现已完成人工复核并确认没有问题，不将错误的首次发现归于用户。','本人已完成人工复核并确认没有问题。')
    ai=ai.replace('；项目源码。；本次AI对话。','；项目源码；本次AI对话。')
    return re.sub(r'\n{3,}','\n\n',body+'## AI 使用声明'+ai)


PARAMETER_QUESTION = "### 阅读结果后的质疑：为什么遍历最优会低于固定超参，提升又往往很小？\n\n记录日期：2026-11-17。本次讨论由阅读固定参数与扫描结果后的疑问引出，依据已保存的实验结果和选参代码核对，未新增训练；作为原第10、17项及主要日志第04项的补充解释，不增加19条发现的计数。\n\n**质疑与判断标准。** 如果固定配置包含在候选集合中，数据划分、预处理、求解设置和评价方式完全一致，那么按同一主指标取最大值，扫描最优不应低于固定配置。本项目按保留六位小数后的指标选择，并列时保留先出现的候选，因此严格数值比较还需考虑这一精度规则。这里的“最优”限定为分类AUC或回归R²最优配置，不能理解成表中各项指标分别最优。\n\n**为什么会看到下降？** 线性SVM由固定C=1改为按AUC选出的C=0.01，AUC由0.910463升至0.911160，准确率由0.834863升至0.844754，但召回率由0.798413降至0.784127。排序改善并不保证默认阈值下漏诊减少。后剪枝最优R²=0.236025低于固定深度3树的0.292150，是剪枝路径候选与最大深度候选两种集合的比较；后剪枝集合不保证包含那棵预剪枝树。预剪枝自身扫描包含深度3，最终仍选深度3，与固定基线相同。Lasso同样选中alpha=0.01，R²约下降0.00000076，源于扫描采用更严格的求解容差与迭代上限，属于求解精度差异。外层独立成绩评价的是训练内选参过程在未参与选参数据上的表现，也不保证超过固定参数成绩。\n\n**提升究竟有多大？**\n\n| 对照 | 主指标 | 扫描配置相对参照的增益 |\n|---|---|---:|\n| 线性SVM，相对固定C=1 | AUC | +0.000697 |\n| RBF SVM，相对固定C=1、gamma=scale | AUC | +0.012532 |\n| 岭回归，相对固定alpha=1 | R² | +0.001586 |\n| SVR，相对固定配置 | R² | +0.083497 |\n| 后剪枝，相对完整树 | R² | +0.232654 |\n\n固定基线已经较好的模型，调参收益主要是微调：深度3和Lasso的固定参数再次被选中；线性SVM六个C的验证AUC约在0.907—0.911之间，候选成绩本身就很接近。原配置不合适时收益明显更大，SVR和完整树的对照说明本次调参并非普遍无效。小数位数也不直接代表实际效果：准确率增加0.01为增加1个百分点，在303例上大致相当于多判对3例（报告使用逐折平均，并非严格按总人数换算）；AUC增加0.01衡量排序改善，不能换算成多判对几例，R²增益也不能解释为准确率增益。\n\n**讨论结论。** 当前结果中的下降分别来自非选参指标的权衡、候选集合不同、数值求解差异或独立评价口径；固定参数已较好和候选表现平稳，则解释了部分模型收益较小。遍历保证的是当前集合内、指定精度与主指标下的最优选择，改善幅度取决于基线与候选的实际差距。已核对的微小增益不足以单独证明稳定的泛化提升；若要判断稳定性，应在隔离的外层评价中比较逐折差值，尚未为本次讨论新增实验。\n"


RBF_AUC_QUESTION = "### 阅读结果后的质疑：为什么RBF核多项分类指标较好，AUC却低于线性核？\n\n记录日期：2026-11-17。对照已保存的固定参数与扫描结果解释指标排序；本次未新增训练，补充原第01、10、11项相关讨论，不增加19条发现的计数。\n\n**先明确比较对象。** “RBF多项指标较好”主要出现在固定超参数对照中，而非两核各自按AUC选出的配置。以下均为相同五折的验证指标均值，precision、recall和F1针对阳性类。\n\n| 配置 | 核 | accuracy | precision | recall | F1 | AUC |\n|---|---|---:|---:|---:|---:|---:|\n| 固定超参数 | 线性 | 0.834863 | 0.836711 | 0.798413 | 0.815262 | 0.910463 |\n| 固定超参数 | RBF | 0.838087 | 0.852606 | 0.783862 | 0.815278 | 0.897508 |\n| 各自按AUC选参 | 线性 | 0.844754 | 0.866493 | 0.784127 | 0.821905 | 0.911160 |\n| 各自按AUC选参 | RBF | 0.838197 | 0.842461 | 0.798413 | 0.818062 | 0.910040 |\n\n固定参数下，RBF准确率、阳性精确率和F1略高，但阳性召回率较低；F1仅高约0.000016，不能理解为明显优势。分别选参后，线性核的准确率、阳性精确率、F1和AUC更高，RBF阳性召回率更高。因此“RBF大部分指标更好”应限定为固定参数表中的部分指标；train_指标反映训练拟合，也不能用来支持验证表现更好。敏感性与阳性recall相同，逐类AUC等重复定义也不能重复计作独立优势。\n\n**为什么这种排序可以同时成立？** accuracy、precision、recall和F1依据默认阈值下的预测类别计算；二分类SVM以decision_function的0为判别边界。AUC则使用连续决策分数，考察阈值变化下的总体排序：随机抽取一名阳性与一名阴性，阳性分数更高计1分，相同计半分，对所有阳性—阴性配对取平均。本项目先在各验证折计算，再对五折取平均。一个模型在0阈值附近恰好多判对一些患者，并不意味着它在所有患者配对上的风险排序都更好。\n\n举例说明（仅为指标机制示意，并非本次患者数据）：两个阳性、两个阴性，线性模型的阳性分数为−0.1、0.8，阴性分数为−0.8、−0.2，在0阈值下准确率为75%，但四个阳性—阴性配对全部排序正确，AUC=1。另一个模型的阳性分数为0.1、0.2，阴性分数为−0.1、0.3，同样准确率75%，却有两个配对顺序错误，AUC=0.5。只看预测类别会遗漏这些排序差异；即使准确率相同，AUC也可能相差很大。\n\n**本次实验的确定结论。** 固定参数RBF在默认阈值下取得了较高的精确率和较低的召回率，并略微提高准确率，但连续分数的总体排序弱于线性核。固定参数的硬标签AUC为RBF 0.834166、线性0.832350，连续分数AUC却为RBF 0.897508、线性0.910463，也直接展示了单一分类决策与完整排序的区别。正式评价采用后者，计算口径没有矛盾。固定参数RBF训练AUC=0.963564、验证AUC=0.897508，差距约0.066056；线性核对应差距约0.013302，这与RBF局部拟合更强、泛化收益不足的解释一致。调参后RBF验证AUC升至0.910040，接近线性的0.911160，表明固定配置影响了表现；目前按AUC仍选择线性核。具体哪些患者配对导致差异，需要逐样本排序误差分析，不能仅由汇总指标推断。\n"


PRUNING_QUESTION = "### 阅读结果后的质疑：后剪枝为什么明显不如预剪枝？\n\n记录日期：2026-11-17。本次沿用保存的结果、逐折指标和逐样本预测，补充主要实验日志第04项；未重新训练模型，也不增加19条发现的计数。\n\n**总体回答。** 固定五折扫描中，深度3预剪枝确实优于当前八个路径位置候选中的最佳后剪枝，但主要差距集中在第4折，不能解释为后剪枝在所有划分上都差。实现采用不同的结构约束，后剪枝候选又较稀疏；这些是本次比较的重要条件。独立外层选参后，两者R²接近且后剪枝略高，说明“后剪枝明显更差”的结论限于本次固定五折扫描，不能推广到方法本身。\n\n**补充质疑：为什么参照表看起来R²较低，其余指标却更好？** 这张表中的“剪枝前”指未剪枝完整树，不是“预剪枝”；必须固定同一个参照对象，并区分指标方向。\n\n| 后剪枝相对的参照 | R²（越高越好） | MAE（越低越好） | RMSE（越低越好） | 树深／叶数的含义 |\n|---|---|---|---|---|\n| 未剪枝完整树 | 0.003372→0.236025，改善 | 0.749126→0.744002，改善 | 1.209231→1.051016，改善 | 11.4→4、82.8→7.4，结构明显缩小 |\n| 深度3预剪枝树 | 0.292150→0.236025，变差 | 0.712077→0.744002，变差 | 1.013903→1.051016，变差 | 深度3→4，叶数8→7.4，结构约束不同 |\n\n因此在这一节中，并不存在“后剪枝R²低于预剪枝，但MAE与RMSE更好”的实测现象：MAE和RMSE都是误差，数值变大表示预测更差，三项预测指标相对深度3树方向一致。若把后剪枝的误差与第一行完整树比较、R²却与第二行预剪枝比较，就会混合两个参照。平均树深和叶节点数是结构统计，不是预测误差指标，也不是越小就必然越好；后剪枝叶数略少却更深，是因为分支更不均匀，已在下文结构分析中解释。不能把“叶子少”作为其泛化更优的证据。\n\n本次表中R²与RMSE并未出现方向冲突。一般而言，在同一验证折、相同真实标签上，R²=1−MSE/Var(y)，所以R²下降必然对应MSE及RMSE上升；MAE因采用绝对损失，可能给出不同排序。跨折分别平均R²与MSE时，各折标签方差不同，也不保证两种均值对任意模型始终同序；这些是一般指标性质，不能替代本表的实际数值判断。\n\n**差距有多大？** 预剪枝与后剪枝的R²分别为0.292150、0.236025，绝对差0.056124；这不是准确率下降5.6个百分点。MAE由0.712077升至0.744002，约增加4.48%；RMSE由1.013903升至1.051016，约增加3.66%；五折平均MSE约增加7.45%。后剪枝相对完整树的R²=0.003372仍有明显改善，说明剪枝已经有效抑制完整树的过拟合，只是当前扫描没有超过深度3。\n\n**逐折定位：平均差距主要来自第4折。**\n\n| 验证折 | 深度3预剪枝R² | 路径位置0.9后剪枝R² | 后剪枝−预剪枝 |\n|---|---:|---:|---:|\n| 1 | 0.467224 | 0.462431 | -0.004793 |\n| 2 | 0.078202 | 0.168426 | 0.090224 |\n| 3 | 0.280311 | 0.262288 | -0.018023 |\n| 4 | 0.279522 | -0.047620 | -0.327141 |\n| 5 | 0.355490 | 0.334602 | -0.020888 |\n\n第1、3、5折的差距较小，第2折后剪枝反而提高约0.090224；第4折下降约0.327141，对五折平均差贡献约−0.065428，超过总差−0.056124，其余四折合起来抵消了一部分下降。若仅为定位来源而查看其余四折，后剪枝平均还高约0.011630；正式评价仍保留全部五折，不能删除不利折重新宣称更优。由此可确定，平均差距主要由某个训练／验证划分下预测结构失配驱动，而非所有折一致的大幅退步。\n\n**结构约束不同，叶子更少也不代表预测更稳。** 预剪枝统一限制最大深度为3，五折均有8个叶节点；后剪枝用训练误差与叶节点数量的惩罚进行权衡，平均7.4个叶节点，但各折深度为4、5、3、4、4。它可以合并某些分支、同时保留其他较深分支，因此与统一截断在第3层的结构不同。后剪枝训练R²=0.580416略高于预剪枝的0.568319，验证R²却更低，训练—验证差距约0.344390与0.276169。这支持当前后剪枝保留的部分训练拟合没有转化为验证收益的解释；但两者平均叶内样本中位数20.6与21.3接近，不能简单说后剪枝所有叶子都过小。\n\n代价复杂度剪枝沿完整树的一条嵌套子树路径选择，它不是枚举任意子树结构；按最大深度得到的树不保证在该路径中。剪枝依据训练误差衡量分支收益，不保证每个被保留的分支对新患者都有益。算法定义参见[scikit-learn代价复杂度剪枝说明](https://scikit-learn.org/stable/modules/tree.html#minimal-cost-complexity-pruning)。这解释了为什么“先长完整再剪”没有必然包含或超过深度3方案的数学保证。\n\n**具体失分机制：同一叶区间的预测均值变化放大了部分患者误差。** 第4折预剪枝MSE=0.892593，后剪枝MSE=1.297884。逐样本记录中，原始零基行号154、真实等级3的患者，预测由1.600000降至0.259843，平方误差增加约5.548463；行号271、真实等级0的患者，预测由2.250000升至2.850000，平方误差增加3.060000；行号3、27、80的三名等级0患者，预测均由1.333333升至2.166667。第4折共60例，后剪枝相对预剪枝的平方误差总和净增24.317511。这些结果直接表明，严重程度的低估与高估同时增加，经过平方损失放大后拉低该折R²。它们能够定位失分样本，但保存的预测不足以确定每次路径分裂与合并的具体因果；不据此臆测其临床特征或节点规则。\n\n**搜索分辨率也限制了结论。** 预剪枝遍历深度1–12及None，共13个候选；后剪枝仅取路径位置{0,0.1,0.25,0.5,0.75,0.9,0.95,1}，共8个候选。这里0.9表示按训练折剪枝路径索引取90%位置，不是删除90%的节点，也不是固定ccp_alpha=0.9；实际五折alpha约为0.035534、0.031561、0.033747、0.039375、0.039506。同一位置在不同训练折对应不同树形。位置0.9与0.95的平均叶数从7.4变为4.4，R²分别为0.236025与0.232057，显示该区间结构变化明显，现有候选并未覆盖完整路径。候选较少本身不证明失分由粗网格造成；可以确定的是，本次只找到了八个位置中的最优，尚未验证细化路径能否超过预剪枝。\n\n**独立选参检查改变了最终判断。** 每个外层训练集合内重新选参后，预剪枝选择的深度为4、4、3、2、4，外层R²=0.209500；后剪枝选择的位置为0.9、0.9、0.95、0.95、0.75，外层R²=0.213837，后者略高约0.004338。两种搜索都受到训练样本变化影响；固定五折扫描同时用于挑选与报告最优成绩，不能用它的差距替代独立评价的差距。外层MAE仍是预剪枝略低（0.748292对0.756324），也说明当前证据不支持所有指标上的统一胜负。\n\n**讨论结论与后续检验。** 在课程固定五折扫描中选择深度3预剪枝更合适；本次后剪枝失分主要集中在第4折，结构与预测均值变化有直接数值证据，不同约束和稀疏路径搜索则是合理的机制解释与搜索限制。独立外层结果表明两种方法当前表现接近，不能认定后剪枝本质更差。若继续检验，应在各训练集合内细化剪枝路径，并以不参与选参的外层折比较逐折差值及叶结构；本次没有执行这项新增实验，也不保证细化后一定反超。\n"
